  'settings.magicPrompts.page.group.sessionExplore.title': 'جولة في الشيفرة',
  'settings.magicPrompts.page.group.sessionExplore.description': 'موجّهات يستخدمها أمر /explore: رسالة مستخدم ظاهرة + تعليمات مخفية. يفحص المستودع ويقدّم توجيهًا منظّمًا — الصورة الكاملة، والوحدات الرئيسية، وكيف ترتبط، ومن أين تبدأ — بدل سرد الملفات واحدًا تلو الآخر.',
  'settings.magicPrompts.page.group.sessionWorkspaceReview.description': 'موجّهات يستخدمها أمر /workspace-review: رسالة مستخدم ظاهرة + تعليمات مخفية. يراجع فروقات مساحة العمل ليتأكد أنها تحقق غرضها وأنها صحيحة وكافية، ويصنّف الملاحظات حسب الخطورة. توجّه التعليمات أيضًا جلسات المراجعة، بما فيها حلقة المراجعة التلقائية.',
  'settings.magicPrompts.page.group.sessionFeaturePlan.title': 'تخطيط الميزة',
  'settings.magicPrompts.page.group.sessionFeaturePlan.description': 'موجّهات يستخدمها أمر /plan-feature: رسالة مستخدم ظاهرة + تعليمات مخفية. يدير حوارًا موجّهًا يبحث في الشيفرة ويطرح أسئلة توضيحية على دفعات صغيرة قبل إعداد خطة تنفيذ.',
  'settings.magicPrompts.page.group.sessionCatchUp.title': 'اللحاق بالعمل',
  'settings.magicPrompts.page.group.sessionCatchUp.description': 'موجّهات يستخدمها أمر /catch-up: رسالة مستخدم ظاهرة + تعليمات مخفية. يجمع سياقًا يراعي الفرع — إيداعات الفرع وPR الخاص به والعمل غير المودَع معًا — ليفهم ما كنت تفعله، ثم يقدّم ملخصًا سهل الفهم وخطوة تالية تركّز على المنتج.',
  'settings.magicPrompts.page.group.sessionDebug.title': 'تصحيح الأخطاء',
  'settings.magicPrompts.page.group.sessionDebug.description': 'موجّهات يستخدمها أمر /debug: رسالة مستخدم ظاهرة + تعليمات مخفية. يدير تحقيقًا موجّهًا في السبب الجذري — يسجّل العَرَض، ويضع فرضيات، ويتحقق منها في الشيفرة، ويؤكد السبب قبل اقتراح إصلاح.',
  'settings.magicPrompts.page.group.sessionWeigh.title': 'موازنة الخيارات',
