  'settings.mcp.page.advanced.codemodeHint': 'عادةً تصبح كل أداة يقدّمها خادم MCP أداة منفصلة يراها النموذج ويستدعيها واحدة تلو الأخرى. مع وضع الشيفرة يحصل النموذج على أداة واحدة تشغّل نصًا برمجيًا قصيرًا، ويستدعي هذا النص أدوات الخادم كدوال. هذا يُبقي السياق صغيرًا عندما يملك الخادم أدوات كثيرة ويسمح بتنفيذ عدة استدعاءات في خطوة واحدة. النماذج الأصغر تكتب هذه النصوص بموثوقية أقل، لذا يمكن تعطيله لكل خادم على حدة.',
